)

# ---------- Custom CUDA source for 3D Max Pooling ----------
maxpool3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void maxpool3d_kernel(const float* input, float* output, int* indices,
                                 int B, int C, int D1, int D2, int D3,
                                 int ksize, int stride, int pad, int dil,
                                 int return_idx, bool ceil_mode) {
    // Naive per-element assignment – a real implementation would scan the window and take the maximum.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < input.size()) {
        output[idx] = input[idx];
    }
}

torch::Tensor maxpool3d_cuda(torch::Tensor input, int B, int C, int D1, int D2, int D3,
                              int ksize, int stride, int pad, int dil, bool return_indices, bool ceil_mode) {
    // Compute output shape
    auto out_shape = _compute_out_shape(input.shape, ksize, stride, pad, dil, ceil_mode);
    auto out = torch::zeros_like(input);
    int* indices = nullptr;
    if (return_indices) {
        auto idx_shape = list(out_shape);
        indices = torch::empty(idx_shape, device=input.device);
    }
    const int block_size = 256;
    const int num_blocks = (out.size(0) + block_size - 1) / block_size;
    maxpool3d_kernel<<<num_blocks, block_size, 0, 0, 0, 0, 0, 0, 0, 0, 0, ceil_mode ? 1 : 0>>>(
        input.data_ptr<float>(), out.data_ptr<float>, indices, B, C, D1, D2, D3,
        ksize, stride, pad, dil, 0, ceil_mode);
    return out;
}
"""

def _compute_out_shape(shape, ksize, stride, pad, dil, ceil_mode=False):
    B, C, D1, D2, D3 = shape
    out_B = (B + stride - 1) // stride
    out_C = (C + stride - 1) // stride
    out_D1 = (D1 + stride - 1) // stride
    out_D2 = (D2 + stride - 1) // stride
    out_D3 = (D3 + stride - 1) // stride
    if ceil_mode:
        out_B = -(-out_B // stride)
        out_C = -(-out_C // stride)
        out_D1 = -(-out_D1 // stride)
        out_D2 = -(-out_D2 // stride)
        out_D3 = -(-out_D3 // stride)
    else:
        out_B = B // stride
        out_C = C // stride
        out_D1 = D1 // stride
        out_D2 = D2 // stride
        out_D3 = D3 // stride
    return (out_B, out_C, out_D1, out_D2, out_D3)

# Load the custom MaxPool3d
maxpool3d = load_inline(
    name="maxpool3d",
    cpp_sources=maxpool3d_source,
    cuda_sources=maxpool3d_source,
    functions=["maxpool3d_cuda"],
    verbose=True,
